<script setup lang="ts">
const props=defineProps<{dnId:number|string;editable:boolean;packages?:unknown}>()
const emit=defineEmits<{saved:[data:any]}>()
const {t}=useI18n(),{bizErrorMessage}=useBizError()
const data=ref<any>(null),loading=ref(false),busy=ref(false),error=ref(''),values=ref<Record<string,number>>({})
const key=(box:number,row:any)=>`${box}:${row.goods_id}:${row.lot_id||0}`
const editable=computed(()=>props.editable&&data.value?.editable&&!busy.value)
const total=(row:any)=>(data.value?.packages||[]).reduce((sum:number,box:any)=>sum+Number(values.value[key(box.package_no,row)]||0),0)
const valid=computed(()=>Object.values(values.value).every(value=>Number.isSafeInteger(Number(value))&&Number(value)>=0)&&data.value?.items.length&&data.value.items.every((row:any)=>total(row)===row.quantity)&&data.value.packages.every((box:any)=>data.value.items.some((row:any)=>Number(values.value[key(box.package_no,row)])>0)))
let generation=0
const load=async()=>{const seq=++generation;loading.value=true;error.value='';data.value=null;values.value={};const result=await httpRequest<any>(`/api/warehouse/dn/${props.dnId}/package-contents`,{onError:e=>{if(seq===generation)error.value=bizErrorMessage(e)}});if(seq!==generation)return;data.value=result;for(const box of result?.packages||[])for(const row of box.contents||[])values.value[key(box.package_no,row)]=row.quantity;loading.value=false}
onBeforeUnmount(()=>generation++)
const save=async(clear=false)=>{if(busy.value||!editable.value||(!clear&&!valid.value))return;const seq=generation,id=props.dnId;if(clear&&!await showConfirm(t('carton-label.clear'),t('carton-label.clear-hint'),t('button.confirm'),t('button.cancel')))return;if(seq!==generation)return;busy.value=true;error.value='';try{const packages=data.value.packages.map((box:any)=>({package_no:box.package_no,contents:clear?null:data.value.items.filter((row:any)=>Number(values.value[key(box.package_no,row)])>0).map((row:any)=>({goods_id:row.goods_id,lot_id:row.lot_id,quantity:Number(values.value[key(box.package_no,row)])}))}));const result=await httpRequest(`/api/warehouse/dn/${id}/package-contents`,{method:'PUT',body:{packages},onError:e=>{if(seq===generation)error.value=bizErrorMessage(e)}});if(result&&seq===generation){emit('saved',result);await load();showToast(t('action-results.success'),'success')}}finally{busy.value=false}}
watch(()=>[props.dnId,props.packages],load,{immediate:true,deep:true})
</script>
<template><details class="carton-contents"><summary>{{t('carton-label.contents')}}</summary><p>{{t('carton-label.contents-hint')}}</p><WAlert v-if="error" tone="block" :title="error"><WButton :disabled="busy" @click="load">{{t('dn.list.retry')}}</WButton></WAlert><WEmptyState v-if="loading" :title="t('common.status.loading')"/><template v-else-if="data"><p v-if="!data.editable">{{t('carton-label.complete-first')}}</p><div v-if="data.packages.length" class="table-scroll"><table><thead><tr><th>{{t('common.entities.goods')}}</th><th>{{t('packing-lots.lot')}}</th><th>{{t('carton-label.packed')}}</th><th v-for="box in data.packages" :key="box.package_no">{{t('carton-label.carton')}} {{box.package_no}}</th><th>{{t('carton-label.assigned')}}</th></tr></thead><tbody><tr v-for="row in data.items" :key="row.goods_id+':'+row.lot_id"><td>{{row.goods_code}}<small>{{row.goods_name}}</small></td><td>{{row.lot_no||'—'}}</td><td>{{row.quantity}}</td><td v-for="box in data.packages" :key="box.package_no"><WInput v-if="editable" v-model.number="values[key(box.package_no,row)]" type="number" min="0" :max="row.quantity" step="1" :aria-label="row.goods_code+' '+(row.lot_no||'')+' '+t('carton-label.carton')+' '+box.package_no"/><span v-else>{{values[key(box.package_no,row)]??'—'}}</span></td><td :class="{invalid:total(row)!==row.quantity}">{{total(row)}} / {{row.quantity}}</td></tr></tbody></table></div><div v-if="editable" class="actions"><WButton :disabled="busy" @click="save(true)">{{t('carton-label.clear')}}</WButton><WButton variant="primary" :disabled="!valid" :loading="busy" @click="save()">{{t('button.save')}}</WButton></div></template></details></template>
<style scoped>.carton-contents{border:1px solid var(--w-border);border-radius:6px;padding:12px 16px;margin-top:12px}summary{cursor:pointer;font-weight:600;font-size:13px}p{font-size:12px;line-height:18px;color:var(--w-text-3);margin:12px 0}.table-scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px}th,td{padding:10px;border-bottom:1px solid var(--w-line);text-align:left;white-space:nowrap}th{font-weight:500;font-size:12px;color:var(--w-text-3)}td>.w-input{width:90px}small{display:block;max-width:220px;white-space:normal;color:var(--w-text-3)}.invalid{color:var(--w-warn-text)}.actions{display:flex;justify-content:flex-end;gap:8px;margin-top:12px}</style>
